(function (window) {
	'use strict';

	function CleverFormsSignaturePad(canvas, options) {
		this.canvas = canvas;
		this.ctx = canvas.getContext('2d');
		this.options = Object.assign({ minWidth: 1.6, maxWidth: 2.8, penColor: '#111827' }, options || {});
		this.strokes = [];
		this.restoredImage = null;
		this.restoredDataUrl = '';
		this.activeStroke = null;
		this.pointerId = null;
		this.cssWidth = 0;
		this.cssHeight = 180;
		this.bindEvents();
		this.resize();
	}

	CleverFormsSignaturePad.prototype.getPoint = function (event) {
		var rect = this.canvas.getBoundingClientRect();
		return {
			x: rect.width ? Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width)) : 0,
			y: rect.height ? Math.max(0, Math.min(1, (event.clientY - rect.top) / rect.height)) : 0,
			t: Date.now()
		};
	};

	CleverFormsSignaturePad.prototype.bindEvents = function () {
		var self = this;
		this.canvas.style.touchAction = 'none';

		this.canvas.addEventListener('pointerdown', function (event) {
			if (event.button !== undefined && event.button !== 0) {
				return;
			}
			event.preventDefault();
			self.pointerId = event.pointerId;
			if (self.canvas.setPointerCapture && event.pointerId !== undefined) {
				self.canvas.setPointerCapture(event.pointerId);
			}
			self.activeStroke = [self.getPoint(event)];
			self.strokes.push(self.activeStroke);
			self.redraw();
		});

		this.canvas.addEventListener('pointermove', function (event) {
			if (!self.activeStroke || (self.pointerId !== null && event.pointerId !== self.pointerId)) {
				return;
			}
			event.preventDefault();
			self.activeStroke.push(self.getPoint(event));
			self.redraw();
		});

		function endStroke(event) {
			if (!self.activeStroke || (self.pointerId !== null && event.pointerId !== self.pointerId)) {
				return;
			}
			self.activeStroke = null;
			self.pointerId = null;
			self.canvas.dispatchEvent(new CustomEvent('cleverforms:signaturechange', { bubbles: true }));
		}

		this.canvas.addEventListener('pointerup', endStroke);
		this.canvas.addEventListener('pointercancel', endStroke);
		this.canvas.addEventListener('lostpointercapture', function () {
			if (self.activeStroke) {
				self.activeStroke = null;
				self.pointerId = null;
				self.canvas.dispatchEvent(new CustomEvent('cleverforms:signaturechange', { bubbles: true }));
			}
		});
	};

	CleverFormsSignaturePad.prototype.resize = function () {
		var rect = this.canvas.getBoundingClientRect();
		var width = Math.max(280, Math.round(rect.width || this.canvas.parentElement.clientWidth || 640));
		var height = Math.max(160, Math.round(rect.height || 180));
		var ratio = Math.max(window.devicePixelRatio || 1, 1);
		this.cssWidth = width;
		this.cssHeight = height;
		this.canvas.width = Math.round(width * ratio);
		this.canvas.height = Math.round(height * ratio);
		this.canvas.style.height = height + 'px';
		this.ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
		this.redraw();
	};

	CleverFormsSignaturePad.prototype.redraw = function () {
		var ctx = this.ctx;
		ctx.clearRect(0, 0, this.cssWidth, this.cssHeight);
		ctx.lineCap = 'round';
		ctx.lineJoin = 'round';
		ctx.strokeStyle = this.options.penColor;
		ctx.fillStyle = this.options.penColor;
		if (this.restoredImage) {
			ctx.drawImage(this.restoredImage, 0, 0, this.cssWidth, this.cssHeight);
		}
		for (var s = 0; s < this.strokes.length; s += 1) {
			var stroke = this.strokes[s];
			if (!stroke.length) {
				continue;
			}
			if (stroke.length === 1) {
				ctx.beginPath();
				ctx.arc(stroke[0].x * this.cssWidth, stroke[0].y * this.cssHeight, this.options.minWidth, 0, Math.PI * 2);
				ctx.fill();
				continue;
			}
			ctx.beginPath();
			ctx.moveTo(stroke[0].x * this.cssWidth, stroke[0].y * this.cssHeight);
			for (var p = 1; p < stroke.length; p += 1) {
				ctx.lineWidth = this.options.maxWidth;
				ctx.lineTo(stroke[p].x * this.cssWidth, stroke[p].y * this.cssHeight);
			}
			ctx.stroke();
		}
	};

	CleverFormsSignaturePad.prototype.clear = function () {
		this.strokes = [];
		this.restoredImage = null;
		this.restoredDataUrl = '';
		this.activeStroke = null;
		this.pointerId = null;
		this.redraw();
		this.canvas.dispatchEvent(new CustomEvent('cleverforms:signaturechange', { bubbles: true }));
	};

	CleverFormsSignaturePad.prototype.isEmpty = function () {
		return this.strokes.length === 0 && !this.restoredImage;
	};

	CleverFormsSignaturePad.prototype.toDataURL = function () {
		return this.isEmpty() ? '' : this.canvas.toDataURL('image/png');
	};

	CleverFormsSignaturePad.prototype.fromDataURL = function (dataUrl) {
		var self = this;
		if (!dataUrl) {
			this.clear();
			return;
		}
		var image = new Image();
		image.onload = function () {
			self.strokes = [];
			self.restoredImage = image;
			self.restoredDataUrl = dataUrl;
			self.redraw();
			self.canvas.dispatchEvent(new CustomEvent('cleverforms:signaturechange', { bubbles: true }));
		};
		image.src = dataUrl;
	};

	window.CleverFormsSignaturePad = CleverFormsSignaturePad;
}(window));
